excels.excel:

EXPORT WITH SHEET="物业水电费收缴台账", HEADER=true,
    MAPPING={"a":"房号","b":"户主","c":"费用类型","d":"应收金额","e":"已收金额","f":"欠缴金额","g":"缴费状态","h":"缴费日期"},
    FORMAT={"d":"#,##0.00","e":"#,##0.00","f":"#,##0.00","h":"yyyy-MM-dd"},
    FORMULAS={
        F2:'D2-E2',F3:'D3-E3',F4:'D4-E4',F5:'D5-E5',F6:'D6-E6',
        D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F5:{color:red,bold:true}
    }
